import { getEnemy, getFaction, getLocation, getNpc, getTitle, getWorldEvent } from '../data/catalog';
import type { GameSave } from '../core/types';
import { getEnemyTraitLabels, getFactionMembershipLabel } from '../engine/rules';

export function buildWorldbookScanText(save: GameSave): string {
  const location = getLocation(save.world.currentLocationId);
  const presentNpcs = Object.keys(save.npcs.relations)
    .map(getNpc)
    .filter(npc => npc?.locationId === save.world.currentLocationId)
    .map(npc => npc!.name);
  const equippedTitle = save.titles.equipped ? getTitle(save.titles.equipped)?.name || save.titles.equipped : '无';
  const activeEvents = save.world.activeEventIds.map(eventId => getWorldEvent(eventId)?.name || eventId);
  const strongFactions = Object.entries(save.factions.reputation)
    .filter(([, reputation]) => Math.abs(reputation) >= 20)
    .map(([factionId, reputation]) => `${getFaction(factionId)?.name || factionId}:${reputation}`);
  const memberships = save.factions.memberships.map(factionId => `${getFaction(factionId)?.name || factionId}:${getFactionMembershipLabel(factionId)}`);
  const combatEnemy = save.combat.enemyId ? getEnemy(save.combat.enemyId) : undefined;
  const combatTraits = getEnemyTraitLabels(combatEnemy);

  return [
    '[裂隙纪元前端版]',
    '国家:华域联邦',
    `区域:${location?.region || '未知区域'}`,
    `地点:${location?.name || save.world.currentLocationId}`,
    `地点标签:${location?.tags.join(' / ') || '无'}`,
    `在场NPC:${presentNpcs.join(' / ') || '无'}`,
    `称号:${equippedTitle}`,
    `关键势力:${strongFactions.join(' / ') || '无'}`,
    `势力身份:${memberships.join(' / ') || '无'}`,
    `活跃事件:${activeEvents.join(' / ') || '无'}`,
    `天气:${save.world.weather}`,
    `时段:${save.time.period}`,
    `玩法:${save.combat.active ? '战斗' : '大世界探索'}`,
    `任务:${save.quests.accepted.join(' / ') || '无'}`,
    `战斗敌人:${save.combat.enemyName || '无'}`,
    `敌人特性:${combatTraits.join(' / ') || '无'}`,
  ].join('\n');
}
