import { getItem, getItemUpgrade } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, Tone } from '../core/types';
import { clampPercent } from './common';
import { changeInventory } from './inventoryEngine';
import { eat } from './survivalEngine';

function formatRequirementList(requiredItems: Record<string, number>): string {
  return Object.entries(requiredItems)
    .map(([itemId, count]) => `${getItem(itemId)?.name || itemId}x${count}`)
    .join('、');
}

function hasRequiredItems(save: GameSave, requiredItems: Record<string, number>): boolean {
  return Object.entries(requiredItems).every(([itemId, count]) => (save.inventory.items[itemId] || 0) >= count);
}

export function useItem(save: GameSave, itemId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const item = getItem(itemId);
  if (!item || (save.inventory.items[itemId] || 0) <= 0) {
    return { save, ok: false, tone: 'red', message: '该物品暂不可使用或数量不足。' };
  }
  if (item.kind === 'food') return eat(save, itemId);
  if (item.kind !== 'consumable') return { save, ok: false, tone: 'amber', message: '该物品不是可直接使用的消耗品。' };

  const effects = item.effects || {};
  const used = appendLog(
    {
      ...changeInventory(save, itemId, -1),
      player: {
        ...save.player,
        hp: clampPercent(save.player.hp + (effects.hp || 0)),
        mp: clampPercent(save.player.mp + (effects.mp || 0)),
        sp: clampPercent(save.player.sp + (effects.sp || 0)),
        realmProgress: clampPercent(save.player.realmProgress + (effects.realmProgress || 0)),
      },
    },
    'green',
    '使用物品',
    `${item.name}已生效。`,
  );
  return { save: used, ok: true, tone: 'green', message: '物品已使用。' };
}

export function buyItem(save: GameSave, itemId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const item = getItem(itemId);
  if (!item) return { save, ok: false, tone: 'red', message: '未知商品。' };
  if (item.kind === 'quest' || item.price <= 0) return { save, ok: false, tone: 'amber', message: '该物品不能直接购买。' };
  if (save.player.credits < item.price) return { save, ok: false, tone: 'red', message: '信点不足。' };
  const bought = appendLog(
    {
      ...changeInventory(save, item.id, 1),
      player: { ...save.player, credits: save.player.credits - item.price },
    },
    'green',
    '购买',
    `购买${item.name}。`,
  );
  return { save: bought, ok: true, tone: 'green', message: '购买完成。' };
}

export function sellItem(save: GameSave, itemId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const item = getItem(itemId);
  if (!item || (save.inventory.items[item.id] || 0) <= 0) return { save, ok: false, tone: 'red', message: '无法出售。' };
  if (item.kind === 'quest') return { save, ok: false, tone: 'amber', message: '任务物品不能出售。' };
  const sold = appendLog(
    {
      ...changeInventory(save, item.id, -1),
      player: { ...save.player, credits: save.player.credits + Math.floor(item.price * 0.5) },
    },
    'green',
    '出售',
    `出售${item.name}。`,
  );
  return { save: sold, ok: true, tone: 'green', message: '出售完成。' };
}

export function equipItem(save: GameSave, itemId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const item = getItem(itemId);
  if (!item || (save.inventory.items[item.id] || 0) <= 0) return { save, ok: false, tone: 'red', message: '装备不存在。' };
  const slot = item.slot || (item.kind === 'weapon' || item.kind === 'armor' || item.kind === 'amplifier' || item.kind === 'accessory' ? item.kind : undefined);
  if (!slot) return { save, ok: false, tone: 'amber', message: '该物品不是装备。' };
  const equipped = appendLog(
    { ...save, inventory: { ...save.inventory, equipped: { ...save.inventory.equipped, [slot]: item.id } } },
    'cyan',
    '装备变更',
    `已装备${item.name}。`,
  );
  return { save: equipped, ok: true, tone: 'cyan', message: '装备完成。' };
}

export function upgradeItem(save: GameSave, itemId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const upgrade = getItemUpgrade(itemId);
  if (!upgrade) return { save, ok: false, tone: 'amber', message: '该装备暂未开放升级路线。' };

  const baseItem = getItem(upgrade.baseItemId);
  const resultItem = getItem(upgrade.resultItemId);
  if (!baseItem || !resultItem) return { save, ok: false, tone: 'red', message: '装备升级数据缺失。' };
  if ((save.inventory.items[upgrade.baseItemId] || 0) <= 0) return { save, ok: false, tone: 'red', message: `背包中没有${baseItem.name}。` };
  if (save.player.credits < upgrade.costCredits) return { save, ok: false, tone: 'red', message: `信点不足，需要${upgrade.costCredits}。` };
  if (!hasRequiredItems(save, upgrade.requiredItems)) {
    const text = formatRequirementList(upgrade.requiredItems);
    return { save, ok: false, tone: 'red', message: `材料不足，需要${text}。` };
  }

  let upgraded: GameSave = {
    ...save,
    player: { ...save.player, credits: save.player.credits - upgrade.costCredits },
  };
  upgraded = changeInventory(upgraded, upgrade.baseItemId, -1);
  Object.entries(upgrade.requiredItems).forEach(([requiredItemId, count]) => {
    upgraded = changeInventory(upgraded, requiredItemId, -count);
  });
  upgraded = changeInventory(upgraded, upgrade.resultItemId, 1);

  const slot = baseItem.slot || (baseItem.kind === 'weapon' || baseItem.kind === 'armor' || baseItem.kind === 'amplifier' || baseItem.kind === 'accessory' ? baseItem.kind : undefined);
  if (slot && save.inventory.equipped[slot] === upgrade.baseItemId) {
    upgraded = {
      ...upgraded,
      inventory: {
        ...upgraded.inventory,
        equipped: { ...upgraded.inventory.equipped, [slot]: upgrade.resultItemId },
      },
    };
  }

  const logged = appendLog(upgraded, 'cyan', '装备升级', `${baseItem.name}升级为${resultItem.name}。`);
  return { save: logged, ok: true, tone: 'cyan', message: `升级完成：${resultItem.name}。` };
}
