import { getTitle } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, Tone } from '../core/types';

export function grantTitle(save: GameSave, titleId: string): GameSave {
  if (!getTitle(titleId) || save.titles.owned.includes(titleId)) return save;
  const owned = [...save.titles.owned, titleId];
  return {
    ...save,
    titles: {
      ...save.titles,
      owned,
      equipped: save.titles.equipped || titleId,
    },
  };
}

export function grantTitles(save: GameSave, titleIds: string[] = []): GameSave {
  return titleIds.reduce((nextSave, titleId) => grantTitle(nextSave, titleId), save);
}

export function equipTitle(save: GameSave, titleId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const title = getTitle(titleId);
  if (!title) return { save, ok: false, tone: 'red', message: '未知称号。' };
  if (!save.titles.owned.includes(titleId)) return { save, ok: false, tone: 'amber', message: '尚未获得该称号。' };
  if (save.titles.equipped === titleId) return { save, ok: false, tone: 'amber', message: `${title.name}已经佩戴。` };

  const nextSave = appendLog(
    { ...save, titles: { ...save.titles, equipped: titleId } },
    title.tone,
    '称号切换',
    `已佩戴称号：${title.name}。`,
  );
  return { save: nextSave, ok: true, tone: title.tone, message: `已佩戴称号：${title.name}。` };
}
