import {
  ENEMIES,
  ITEM_UPGRADES,
  LOCATIONS,
  NPC_INTERACTION_RULES,
  NPCS,
  QUESTS,
  ROUTES,
  WORLD_EVENTS,
  getFaction,
  getItem,
  getLocation,
  getNpc,
  getQuest,
  getTitle,
  getWorldEvent,
} from '../data/catalog';
import { SAVE_SCHEMA_VERSION, type ConditionDefinition, type GameSave } from '../core/types';
import { buildRoutePlan } from '../engine/worldEngine';
import { buildSituationSummary } from './generationService';
import { buildWorldbookScanText } from './worldbookRouteService';

export type HealthCheckItem = {
  ok: boolean;
  label: string;
  message: string;
};

function conditionReferencesExist(condition: ConditionDefinition): boolean {
  switch (condition.kind) {
    case 'questAccepted':
    case 'questCompleted':
      return Boolean(getQuest(condition.questId));
    case 'factionReputationAtLeast':
    case 'factionMember':
      return Boolean(getFaction(condition.factionId));
    case 'titleOwned':
      return Boolean(getTitle(condition.titleId));
    case 'activeEvent':
    case 'completedEvent':
      return Boolean(getWorldEvent(condition.eventId));
    case 'relationAtLeast':
      return Boolean(getNpc(condition.npcId));
    case 'itemAtLeast':
      return Boolean(getItem(condition.itemId));
    case 'locationDiscovered':
    case 'locationUnlocked':
    case 'currentLocation':
      return Boolean(getLocation(condition.locationId));
    default:
      return true;
  }
}

function allStaticConditions(): ConditionDefinition[] {
  return [
    ...LOCATIONS.flatMap(location => location.unlockConditions || []),
    ...QUESTS.flatMap(quest => quest.unlockConditions || []),
    ...ENEMIES.flatMap(enemy => enemy.encounterConditions || []),
    ...WORLD_EVENTS.flatMap(event => event.triggerConditions || []),
    ...NPC_INTERACTION_RULES.flatMap(rule => rule.conditions || []),
  ];
}

export function runHealthCheck(save: GameSave): HealthCheckItem[] {
  const checks: HealthCheckItem[] = [];
  const currentLocation = getLocation(save.world.currentLocationId);

  checks.push({
    ok: save.schemaVersion === SAVE_SCHEMA_VERSION,
    label: '存档版本',
    message: `当前 schemaVersion=${save.schemaVersion}，项目版本=${SAVE_SCHEMA_VERSION}。`,
  });
  checks.push({
    ok: Boolean(currentLocation),
    label: '当前位置',
    message: currentLocation ? currentLocation.name : `缺失地点 ${save.world.currentLocationId}`,
  });
  checks.push({
    ok: save.player.credits >= 0 && save.player.sourceCrystals >= 0 && save.player.darkChips >= 0,
    label: '货币',
    message: '信点、源晶、暗筹不应为负数。',
  });
  checks.push({
    ok: Object.keys(save.inventory.items).every(itemId => Boolean(getItem(itemId))),
    label: '背包引用',
    message: '背包物品必须存在于静态物品表。',
  });
  checks.push({
    ok: Object.values(save.inventory.items).every(count => Number.isFinite(count) && count > 0),
    label: '背包数量',
    message: '背包物品数量必须为正数。',
  });
  checks.push({
    ok: Object.values(save.inventory.equipped).every(itemId => !itemId || Boolean(getItem(itemId))),
    label: '装备引用',
    message: '已装备物品必须存在于静态物品表。',
  });
  checks.push({
    ok: Object.values(save.inventory.equipped).every(itemId => !itemId || (save.inventory.items[itemId] || 0) > 0),
    label: '装备持有',
    message: '已装备物品应同时存在于背包中。',
  });
  checks.push({
    ok: [...save.quests.accepted, ...save.quests.completed].every(questId => Boolean(getQuest(questId))),
    label: '任务引用',
    message: '任务 id 必须存在于静态任务表。',
  });
  checks.push({
    ok: Object.keys(save.factions.reputation).every(factionId => Boolean(getFaction(factionId))) && save.factions.memberships.every(factionId => Boolean(getFaction(factionId))),
    label: '势力引用',
    message: '存档势力声望与身份必须存在于静态势力表。',
  });
  checks.push({
    ok: save.titles.owned.every(titleId => Boolean(getTitle(titleId))) && (!save.titles.equipped || Boolean(getTitle(save.titles.equipped))),
    label: '称号引用',
    message: '存档称号必须存在于静态称号表。',
  });
  checks.push({
    ok: [...save.world.activeEventIds, ...save.events.completedEventIds].every(eventId => Boolean(getWorldEvent(eventId))),
    label: '世界事件引用',
    message: '存档事件必须存在于静态世界事件表。',
  });
  checks.push({
    ok: ROUTES.every(route => Boolean(getLocation(route.from) && getLocation(route.to))),
    label: '路线引用',
    message: '路线两端必须存在于静态地点表。',
  });
  checks.push({
    ok: QUESTS.filter(quest => quest.locationId && (save.quests.accepted.includes(quest.id) || !save.quests.completed.includes(quest.id))).every(quest => buildRoutePlan(save, quest.locationId!).ok || !buildRoutePlan(save, quest.locationId!).steps.length),
    label: '任务路线',
    message: '已接取或可见任务应能给出可走路径，或明确显示锁定/阻塞原因。',
  });
  checks.push({
    ok: save.world.unlockedLocationIds.includes(save.world.currentLocationId),
    label: '当前位置解锁',
    message: '当前位置应处于已解锁地点列表中。',
  });
  checks.push({
    ok: NPCS.every(npc => Boolean(getLocation(npc.locationId))),
    label: 'NPC地点',
    message: 'NPC 常驻地点必须存在于静态地点表。',
  });
  checks.push({
    ok: NPC_INTERACTION_RULES.every(rule => Boolean(getNpc(rule.npcId))),
    label: 'NPC互动',
    message: 'NPC互动规则必须指向现有NPC。',
  });
  checks.push({
    ok: NPC_INTERACTION_RULES.every(rule => Object.keys(rule.factionReputation || {}).every(factionId => Boolean(getFaction(factionId)))),
    label: 'NPC互动声望',
    message: 'NPC互动声望变化必须指向静态势力表。',
  });
  checks.push({
    ok: NPC_INTERACTION_RULES.every(rule => (rule.grantFactionMembershipIds || []).every(factionId => Boolean(getFaction(factionId)))),
    label: 'NPC互动身份',
    message: 'NPC互动授予身份必须指向静态势力表。',
  });
  checks.push({
    ok: NPC_INTERACTION_RULES.every(rule => (rule.rewardTitleIds || []).every(titleId => Boolean(getTitle(titleId)))),
    label: 'NPC互动称号',
    message: 'NPC互动授予称号必须存在于静态称号表。',
  });
  checks.push({
    ok: NPC_INTERACTION_RULES.every(rule => [...(rule.rewardEventIds || []), ...(rule.completeEventIds || [])].every(eventId => Boolean(getWorldEvent(eventId)))),
    label: 'NPC互动事件',
    message: 'NPC互动事件必须存在于静态世界事件表。',
  });
  checks.push({
    ok: QUESTS.every(quest => Object.keys(quest.rewardItems).every(itemId => Boolean(getItem(itemId)))),
    label: '任务奖励',
    message: '任务奖励物品必须存在于静态物品表。',
  });
  checks.push({
    ok: QUESTS.every(quest => !quest.sourceFaction || Boolean(getFaction(quest.sourceFaction))),
    label: '任务势力',
    message: '任务来源势力必须存在于静态势力表。',
  });
  checks.push({
    ok: QUESTS.every(quest => Object.keys(quest.rewardFactionReputation || {}).every(factionId => Boolean(getFaction(factionId)))),
    label: '任务声望奖励',
    message: '任务声望奖励必须指向静态势力表。',
  });
  checks.push({
    ok: QUESTS.every(quest => (quest.rewardFactionMembershipIds || []).every(factionId => Boolean(getFaction(factionId)))),
    label: '任务势力身份奖励',
    message: '任务势力身份奖励必须指向静态势力表。',
  });
  checks.push({
    ok: QUESTS.every(quest => (quest.rewardTitleIds || []).every(titleId => Boolean(getTitle(titleId)))),
    label: '任务称号奖励',
    message: '任务称号奖励必须存在于静态称号表。',
  });
  checks.push({
    ok: QUESTS.every(quest => [...(quest.rewardEventIds || []), ...(quest.completeEventIds || [])].every(eventId => Boolean(getWorldEvent(eventId)))),
    label: '任务事件奖励',
    message: '任务事件奖励必须存在于静态世界事件表。',
  });
  checks.push({
    ok: QUESTS.every(quest => (quest.rewardUnlockLocationIds || []).every(locationId => Boolean(getLocation(locationId)))),
    label: '任务地点解锁',
    message: '任务解锁地点必须存在于静态地点表。',
  });
  checks.push({
    ok: ENEMIES.every(enemy => (enemy.habitatIds || []).every(locationId => Boolean(getLocation(locationId)))),
    label: '敌人栖息地',
    message: '敌人栖息地必须存在于静态地点表。',
  });
  checks.push({
    ok: ENEMIES.every(enemy => Object.keys(enemy.dropItems || {}).every(itemId => Boolean(getItem(itemId)))),
    label: '敌人掉落',
    message: '敌人掉落物必须存在于静态物品表。',
  });
  checks.push({
    ok: ITEM_UPGRADES.every(upgrade => Boolean(getItem(upgrade.baseItemId) && getItem(upgrade.resultItemId))),
    label: '装备升级',
    message: '装备升级的基础物品与成品必须存在于静态物品表。',
  });
  checks.push({
    ok: ITEM_UPGRADES.every(upgrade => Object.keys(upgrade.requiredItems).every(itemId => Boolean(getItem(itemId)))),
    label: '升级材料',
    message: '装备升级材料必须存在于静态物品表。',
  });
  checks.push({
    ok: allStaticConditions().every(conditionReferencesExist),
    label: '条件引用',
    message: '地点、任务、敌人条件引用必须指向现有静态数据。',
  });
  checks.push({
    ok: !save.combat.active || Boolean(save.combat.enemyId && save.combat.enemyHp !== undefined),
    label: '战斗状态',
    message: '战斗中必须有敌人 id 和生命值。',
  });
  checks.push({
    ok: buildWorldbookScanText(save).length > 20,
    label: '世界书扫描词',
    message: '扫描词不应为空。',
  });

  return checks;
}

export function buildDebugSnapshot(save: GameSave): string {
  return [
    '【权威局势】',
    buildSituationSummary(save),
    '',
    '【世界书扫描词】',
    buildWorldbookScanText(save),
    '',
    '【健康检查】',
    runHealthCheck(save)
      .map(item => `${item.ok ? 'OK' : 'ERR'} ${item.label}: ${item.message}`)
      .join('\n'),
  ].join('\n');
}
