import { getWorldEvent, WORLD_EVENTS } from '../data/catalog';
import { createId, nowMs } from '../core/save';
import type { GameSave, Tone } from '../core/types';
import { checkConditions } from './conditionEngine';

export function recordWorldEvent(save: GameSave, eventId: string, title?: string, message?: string, tone: Tone = 'cyan'): GameSave {
  const definition = getWorldEvent(eventId);
  const record = {
    id: createId('event'),
    eventId,
    createdAt: nowMs(),
    title: title || definition?.name || eventId,
    message: message || definition?.description || eventId,
    tone,
  };
  return {
    ...save,
    events: {
      ...save.events,
      records: [record, ...save.events.records].slice(0, 80),
    },
  };
}

export function activateWorldEvent(save: GameSave, eventId: string): GameSave {
  if (!getWorldEvent(eventId)) return save;
  const activeEventIds = Array.from(new Set([...save.world.activeEventIds, eventId]));
  return recordWorldEvent({ ...save, world: { ...save.world, activeEventIds } }, eventId);
}

export function activateWorldEvents(save: GameSave, eventIds: string[] = []): GameSave {
  return eventIds.reduce((nextSave, eventId) => activateWorldEvent(nextSave, eventId), save);
}

export function completeWorldEvent(save: GameSave, eventId: string): GameSave {
  if (!getWorldEvent(eventId)) return save;
  const completedEventIds = Array.from(new Set([...save.events.completedEventIds, eventId]));
  const activeEventIds = save.world.activeEventIds.filter(id => id !== eventId);
  return recordWorldEvent(
    {
      ...save,
      world: { ...save.world, activeEventIds },
      events: { ...save.events, completedEventIds },
    },
    eventId,
    `${getWorldEvent(eventId)?.name || eventId} 已收束`,
    getWorldEvent(eventId)?.description,
    'green',
  );
}

export function completeWorldEvents(save: GameSave, eventIds: string[] = []): GameSave {
  return eventIds.reduce((nextSave, eventId) => completeWorldEvent(nextSave, eventId), save);
}

export function evaluateWorldEventTriggers(save: GameSave): { save: GameSave; triggeredEventIds: string[] } {
  const triggerableEvents = WORLD_EVENTS.filter(event => {
    if (!event.triggerConditions?.length) return false;
    if (save.world.activeEventIds.includes(event.id)) return false;
    if (save.events.completedEventIds.includes(event.id)) return false;
    return checkConditions(save, event.triggerConditions).ok;
  });

  const triggeredEventIds = triggerableEvents.map(event => event.id);
  return {
    save: activateWorldEvents(save, triggeredEventIds),
    triggeredEventIds,
  };
}
