import { getPeriod, getSeason } from '../core/save';
import type { GameSave } from '../core/types';

export function advanceTime(save: GameSave, minutes: number): GameSave {
  const totalHours = save.time.hour + Math.floor(minutes / 60);
  const nextHour = ((totalHours % 24) + 24) % 24;
  const extraDays = Math.floor(totalHours / 24);
  const nextDayRaw = save.time.day + extraDays;
  const extraMonths = Math.floor((nextDayRaw - 1) / 30);
  const nextDay = ((nextDayRaw - 1) % 30) + 1;
  const nextMonthRaw = save.time.month + extraMonths;
  const extraYears = Math.floor((nextMonthRaw - 1) / 12);
  const nextMonth = ((nextMonthRaw - 1) % 12) + 1;

  return {
    ...save,
    time: {
      year: save.time.year + extraYears,
      month: nextMonth,
      day: nextDay,
      hour: nextHour,
      period: getPeriod(nextHour),
      season: getSeason(nextMonth),
      turn: save.time.turn + 1,
    },
  };
}
