export async function writeNarrationToChat(playerText: string, aiText: string): Promise<void> {
  if (typeof createChatMessages !== 'function') return;

  await createChatMessages(
    [
      {
        role: 'user',
        name: '{{user}}',
        message: playerText,
        data: {},
        extra: { riftEraFrontend: { type: 'player_action', savedAt: Date.now() } },
      },
      {
        role: 'assistant',
        message: aiText,
        data: {},
        extra: { riftEraFrontend: { type: 'ai_narration', savedAt: Date.now() } },
      },
    ],
    { insert_before: 'end', refresh: 'affected' },
  );
}
