export function getConnectedLocationIds(locationId: string): string[] {
  return ROUTES.flatMap(route => {
    if (route.from === locationId) return [route.to];
    if (route.to === locationId) return [route.from];
    return [];
  });
}

export const LOCATIONS: LocationDefinition[] = LOCATION_BASE.map(location => ({
  ...location,
  connections: getConnectedLocationIds(location.id),
}));

export function getInitialUnlockedLocationIds(): string[] {
  return LOCATIONS.filter(location => !location.unlockConditions || location.unlockConditions.length === 0).map(location => location.id);
}

