export function getInitialFactionReputation(): Record<string, number> {
  return Object.fromEntries(
    FACTIONS.map(faction => {
      const value = faction.stance === 'friendly' ? 10 : faction.stance === 'lawful' ? 0 : faction.stance === 'hostile' ? -40 : 0;
      return [faction.id, value];
    }),
  );
}

