export function getLocation(id: string): LocationDefinition | undefined {
  return LOCATIONS.find(location => location.id === id);
}

export function getRoute(fromId: string, toId: string): RouteDefinition | undefined {
  return ROUTES.find(route => (route.from === fromId && route.to === toId) || (route.from === toId && route.to === fromId));
}

export function getFaction(id: string): FactionDefinition | undefined {
  return FACTIONS.find(faction => faction.id === id);
}

export function getTitle(id: string): TitleDefinition | undefined {
  return TITLES.find(title => title.id === id);
}

export function getWorldEvent(id: string): WorldEventDefinition | undefined {
  return WORLD_EVENTS.find(event => event.id === id);
}

export function getRealm(id: string): RealmDefinition | undefined {
  return REALMS.find(realm => realm.id === id);
}

export function getTalentGrade(id: string): TalentGradeDefinition | undefined {
  return TALENT_GRADES.find(grade => grade.id === id);
}

export function getAbilityType(id: string): AbilityTypeDefinition | undefined {
  return ABILITY_TYPES.find(abilityType => abilityType.id === id);
}

export function getNpc(id: string): NpcDefinition | undefined {
  return NPCS.find(npc => npc.id === id);
}

export function getItem(id: string): ItemDefinition | undefined {
  return ITEMS.find(item => item.id === id);
}

export function getItemUpgrade(baseItemId: string): EquipmentUpgradeDefinition | undefined {
  return ITEM_UPGRADES.find(upgrade => upgrade.baseItemId === baseItemId);
}

export function getQuest(id: string): QuestDefinition | undefined {
  return QUESTS.find(quest => quest.id === id);
}

export function getEnemy(id: string): EnemyDefinition | undefined {
  return ENEMIES.find(enemy => enemy.id === id);
}
