import type { GameSave } from '../core/types';

export function changeInventory(save: GameSave, itemId: string, delta: number): GameSave {
  const current = save.inventory.items[itemId] || 0;
  const next = current + delta;
  const items = { ...save.inventory.items };
  if (next <= 0) {
    delete items[itemId];
  } else {
    items[itemId] = next;
  }
  return { ...save, inventory: { ...save.inventory, items } };
}
