import { getFaction, getItem, getLocation, getTitle, getWorldEvent } from '../data/catalog';
import type { GameSave, LocationDefinition, QuestDefinition } from '../core/types';
import { getFactionMembershipLabel, getFactionStanding } from './factionEngine';

export type QuestRewardPreview = {
  rewardLines: string[];
  unlockLines: string[];
};

function formatSigned(value: number): string {
  return value > 0 ? `+${value}` : String(value);
}

function locationUnlockLabel(location: LocationDefinition): string {
  if (location.id === 'thorn_chamber_dark_market' || location.tags.includes('暗筹') || location.tags.includes('灰色交易')) {
    return `暗拍入口：${location.name}`;
  }

  if (location.tags.includes('前线') || location.id === 'great_wasteland_outpost' || location.id === 'yuankou_observation') {
    return `前线权限：${location.name}`;
  }

  return `新地点：${location.name}`;
}

function joinNamed(ids: string[], resolver: (id: string) => string | undefined): string {
  return ids.map(id => resolver(id) || id).join('、');
}

export function buildQuestRewardPreview(quest: QuestDefinition): QuestRewardPreview {
  const rewardLines: string[] = [];
  const unlockLines: string[] = [];

  if (quest.rewardCredits > 0) rewardLines.push(`${quest.rewardCredits} 信点`);

  const itemLines = Object.entries(quest.rewardItems)
    .filter(([, count]) => count > 0)
    .map(([itemId, count]) => `${getItem(itemId)?.name || itemId} x${count}`);
  if (itemLines.length) rewardLines.push(`物资：${itemLines.join('、')}`);

  const reputationLines = Object.entries(quest.rewardFactionReputation || {}).map(([factionId, delta]) => {
    const factionName = getFaction(factionId)?.name || factionId;
    return `${factionName} ${formatSigned(delta)}`;
  });
  if (reputationLines.length) rewardLines.push(`声望：${reputationLines.join('、')}`);

  if (quest.rewardFactionMembershipIds?.length) {
    const membershipLines = quest.rewardFactionMembershipIds.map(factionId => {
      const factionName = getFaction(factionId)?.name || factionId;
      return `${factionName}（${getFactionMembershipLabel(factionId)}）`;
    });
    rewardLines.push(`势力身份：${membershipLines.join('、')}`);
  }

  if (quest.rewardTitleIds?.length) {
    rewardLines.push(`称号/权限：${joinNamed(quest.rewardTitleIds, id => getTitle(id)?.name)}`);
  }

  if (quest.rewardUnlockLocationIds?.length) {
    quest.rewardUnlockLocationIds.forEach(locationId => {
      const location = getLocation(locationId);
      unlockLines.push(location ? locationUnlockLabel(location) : `新地点：${locationId}`);
    });
  }

  if (quest.rewardEventIds?.length) {
    unlockLines.push(`新增事件：${joinNamed(quest.rewardEventIds, id => getWorldEvent(id)?.name)}`);
  }

  if (quest.completeEventIds?.length) {
    unlockLines.push(`收束事件：${joinNamed(quest.completeEventIds, id => getWorldEvent(id)?.name)}`);
  }

  return { rewardLines, unlockLines };
}

export function buildQuestCompletionFeedback(before: GameSave, after: GameSave, quest: QuestDefinition): string[] {
  const lines: string[] = [];
  if (quest.rewardCredits > 0) lines.push(`获得 ${quest.rewardCredits} 信点`);

  const itemLines = Object.entries(quest.rewardItems)
    .filter(([, count]) => count > 0)
    .map(([itemId, count]) => `${getItem(itemId)?.name || itemId} x${count}`);
  if (itemLines.length) lines.push(`物资 ${itemLines.join('、')}`);

  const reputationLines = Object.entries(after.factions.reputation)
    .map(([factionId, reputation]) => {
      const previous = before.factions.reputation[factionId] || 0;
      const delta = reputation - previous;
      if (delta === 0) return '';
      const factionName = getFaction(factionId)?.name || factionId;
      return `${factionName} ${formatSigned(delta)}（${getFactionStanding(reputation)}）`;
    })
    .filter(Boolean);
  if (reputationLines.length) lines.push(`声望 ${reputationLines.join('、')}`);

  const newTitleIds = after.titles.owned.filter(titleId => !before.titles.owned.includes(titleId));
  if (newTitleIds.length) lines.push(`获得称号 ${joinNamed(newTitleIds, id => getTitle(id)?.name)}`);

  const newMembershipIds = after.factions.memberships.filter(factionId => !before.factions.memberships.includes(factionId));
  if (newMembershipIds.length) {
    const membershipLines = newMembershipIds.map(factionId => {
      const factionName = getFaction(factionId)?.name || factionId;
      return `${factionName}（${getFactionMembershipLabel(factionId)}）`;
    });
    lines.push(`获得势力身份 ${membershipLines.join('、')}`);
  }

  const newLocationIds = after.world.unlockedLocationIds.filter(locationId => !before.world.unlockedLocationIds.includes(locationId));
  if (newLocationIds.length) {
    lines.push(
      newLocationIds
        .map(locationId => {
          const location = getLocation(locationId);
          return location ? locationUnlockLabel(location) : `新地点：${locationId}`;
        })
        .join('、'),
    );
  }

  const newEventIds = after.world.activeEventIds.filter(eventId => !before.world.activeEventIds.includes(eventId));
  if (newEventIds.length) lines.push(`新增事件 ${joinNamed(newEventIds, id => getWorldEvent(id)?.name)}`);

  const completedEventIds = after.events.completedEventIds.filter(eventId => !before.events.completedEventIds.includes(eventId));
  if (completedEventIds.length) lines.push(`收束事件 ${joinNamed(completedEventIds, id => getWorldEvent(id)?.name)}`);

  return lines;
}

export function buildQuestUnlockFeedback(before: GameSave, after: GameSave): string[] {
  const newLocationIds = after.world.unlockedLocationIds.filter(locationId => !before.world.unlockedLocationIds.includes(locationId));
  return newLocationIds.map(locationId => {
    const location = getLocation(locationId);
    return location ? locationUnlockLabel(location) : `新地点：${locationId}`;
  });
}
