import { getFaction, getItem, getLocation, getNpc, getQuest, getTitle, getWorldEvent, REALMS } from '../data/catalog';
import type { ConditionDefinition, GameSave } from '../core/types';

export type ConditionCheck = {
  ok: boolean;
  failed: string[];
};

function realmOrder(realmName: string): number {
  return REALMS.find(realm => realm.name === realmName || realm.id === realmName)?.order || 0;
}

export function describeCondition(condition: ConditionDefinition): string {
  switch (condition.kind) {
    case 'questCompleted':
      return `完成任务：${getQuest(condition.questId)?.name || condition.questId}`;
    case 'questAccepted':
      return `接取任务：${getQuest(condition.questId)?.name || condition.questId}`;
    case 'questProgress':
      return `事件进度 ${condition.eventId} 达到 ${condition.count}`;
    case 'relationAtLeast':
      return `${getNpc(condition.npcId)?.name || condition.npcId} 好感达到 ${condition.favor}`;
    case 'itemAtLeast':
      return `持有 ${getItem(condition.itemId)?.name || condition.itemId} x${condition.count}`;
    case 'locationDiscovered':
      return `发现地点：${getLocation(condition.locationId)?.name || condition.locationId}`;
    case 'locationUnlocked':
      return `解锁地点：${getLocation(condition.locationId)?.name || condition.locationId}`;
    case 'currentLocation':
      return `位于 ${getLocation(condition.locationId)?.name || condition.locationId}`;
    case 'activeEvent':
      return `世界事件激活：${condition.eventId}`;
    case 'completedEvent':
      return `完成世界事件：${getWorldEvent(condition.eventId)?.name || condition.eventId}`;
    case 'factionReputationAtLeast':
      return `${getFaction(condition.factionId)?.name || condition.factionId} 声望达到 ${condition.reputation}`;
    case 'factionMember':
      return `拥有势力身份：${getFaction(condition.factionId)?.name || condition.factionId}`;
    case 'titleOwned':
      return `拥有称号：${getTitle(condition.titleId)?.name || condition.titleId}`;
    case 'playerRealmAtLeast':
      return `境界达到 ${condition.realm}`;
    case 'creditsAtLeast':
      return `信点达到 ${condition.amount}`;
    default:
      return '未知条件';
  }
}

export function checkCondition(save: GameSave, condition: ConditionDefinition): boolean {
  switch (condition.kind) {
    case 'questCompleted':
      return save.quests.completed.includes(condition.questId);
    case 'questAccepted':
      return save.quests.accepted.includes(condition.questId);
    case 'questProgress':
      return (save.quests.progress[condition.eventId] || 0) >= condition.count;
    case 'relationAtLeast':
      return (save.npcs.relations[condition.npcId]?.favor || 0) >= condition.favor;
    case 'itemAtLeast':
      return (save.inventory.items[condition.itemId] || 0) >= condition.count;
    case 'locationDiscovered':
      return save.world.discoveredLocationIds.includes(condition.locationId);
    case 'locationUnlocked':
      return save.world.unlockedLocationIds.includes(condition.locationId);
    case 'currentLocation':
      return save.world.currentLocationId === condition.locationId;
    case 'activeEvent':
      return save.world.activeEventIds.includes(condition.eventId);
    case 'completedEvent':
      return save.events.completedEventIds.includes(condition.eventId);
    case 'factionReputationAtLeast':
      return (save.factions.reputation[condition.factionId] || 0) >= condition.reputation;
    case 'factionMember':
      return save.factions.memberships.includes(condition.factionId);
    case 'titleOwned':
      return save.titles.owned.includes(condition.titleId);
    case 'playerRealmAtLeast':
      return realmOrder(save.player.realm) >= realmOrder(condition.realm);
    case 'creditsAtLeast':
      return save.player.credits >= condition.amount;
    default:
      return false;
  }
}

export function checkConditions(save: GameSave, conditions: ConditionDefinition[] = []): ConditionCheck {
  const failed = conditions.filter(condition => !checkCondition(save, condition)).map(describeCondition);
  return { ok: failed.length === 0, failed };
}

export function formatFailedConditions(check: ConditionCheck, fallback = '条件未满足。'): string {
  if (check.ok) return '';
  return check.failed.length > 0 ? check.failed.join('；') : fallback;
}
