import { ABILITY_TYPES, ENEMIES, FACTIONS, ITEMS, NPCS, QUESTS, REALMS, TALENT_GRADES, TITLES, WORLD_EVENTS, getFaction, getItem, getItemUpgrade, getLocation, getNpc, getQuest, getTitle, getWorldEvent, } from '../data/catalog';
import { dispatchGameAction } from '../core/actions';
import { COMBAT_SKILL_COSTS, buildRoutePlan, getAvailableEnemies, getEnemyTraitLabels, getEnemyCounterHints, getEnemyVictoryAdvice, getAvailableNpcInteractionRules, getFactionMembershipLabel, getFactionStanding, getQuestAvailability, getQuestProgressText, buildQuestRewardPreview, getPlayerCombatStats, getTravelTargets, refreshUnlockedLocations, } from '../engine/rules';
import { createInitialGameSave, exportGameSaveText, importGameSaveText, loadGameSave, persistGameSave, } from '../core/save';
import { buildDebugSnapshot, runHealthCheck } from '../services/debugService';
import { buildSituationSummary } from '../services/generationService';
